using System;
using System.Collections.Generic;
using System.Reflection;
using GameplayTags;
internal static class Program
{
 static readonly FieldInfo Buckets=typeof(TagStorage).GetField("m_Buckets",BindingFlags.NonPublic|BindingFlags.Instance), Mask=typeof(TagStorage).GetField("m_BucketMask",BindingFlags.NonPublic|BindingFlags.Instance);
 static GameplayTag[] Flat, Deep, Other; static int Cases, Skipped;
 static void Register(){var names=new List<GameplayTagRegistration>();for(int i=0;i<320;i++)names.Add(new GameplayTagRegistration("F.G"+(i%13)+".L"+i));var a=new string[257];a[0]="Deep";for(int i=1;i<a.Length;i++)a[i]=a[i-1]+".N";var b=new string[301];b[0]="Other";for(int i=1;i<b.Length;i++)b[i]=b[i-1]+".N";names.Add(new GameplayTagRegistration(a[a.Length-1]));names.Add(new GameplayTagRegistration(b[b.Length-1]));GameplayTagManager.Initialize(names.ToArray());Flat=new GameplayTag[320];for(int i=0;i<320;i++)Flat[i]=GameplayTagManager.RequestTag("F.G"+(i%13)+".L"+i);Deep=Array.ConvertAll(a,GameplayTagManager.RequestTag);Other=Array.ConvertAll(b,GameplayTagManager.RequestTag);}
 static GameplayTagContainer Make(int recipe,int count,int shape,int reserve){var c=new GameplayTagContainer(reserve);var rng=new Random(recipe);if((recipe&1)!=0){foreach(var t in Flat)c.AddTag(t);for(int i=Flat.Length-1;i>=0;i--)c.RemoveTag(Flat[i]);}if((recipe&2)!=0){c.AddTag(Other[300]);c.RemoveTag(Other[300]);}var tags=shape==0?Flat:shape==1?Deep:Other;var ids=new List<int>();for(int i=0;i<tags.Length;i++)ids.Add(i);for(int i=ids.Count-1;i>0;i--){int j=rng.Next(i+1),v=ids[i];ids[i]=ids[j];ids[j]=v;}if(shape==3){c.AddTag(Other[300]);}else for(int i=0;i<count&&i<ids.Count;i++)c.AddTag(tags[ids[i]]);if((recipe&4)!=0){for(int i=0;i<Math.Min(8,ids.Count);i++)c.AddTag(tags[ids[i]]);for(int i=0;i<Math.Min(4,ids.Count);i++)c.RemoveTag(tags[ids[i]]);}c.m_SerializedExplicitTags=new List<string>(17){"stale","cache"};return c;}
 static object[] Refs(GameplayTagContainer c){var s=c.Indices.Storage;return new object[]{s,s.Entries,s.ExplicitIndices,Buckets.GetValue(s),c.m_SerializedExplicitTags};}
 static string Identity(object[] before,GameplayTagContainer c){var after=Refs(c);var result="";for(int i=0;i<before.Length;i++)result+=ReferenceEquals(before[i],after[i])?"S":"C";return result;}
 static string Diff(GameplayTagContainer a,GameplayTagContainer b){var x=a.Indices.Storage;var y=b.Indices.Storage;if(x.Count!=y.Count||x.ExplicitCount!=y.ExplicitCount||(int)Mask.GetValue(x)!=(int)Mask.GetValue(y))return "counts/mask";if(x.Entries.Length!=y.Entries.Length)return "entry length";for(int i=0;i<x.Entries.Length;i++){var p=x.Entries[i];var q=y.Entries[i];if(p.Id!=q.Id||p.Count!=q.Count||p.ExplicitCount!=q.ExplicitCount||p.ExplicitIndex!=q.ExplicitIndex)return "entry "+i+" of "+x.Count;}if(x.ExplicitIndices.Length!=y.ExplicitIndices.Length)return "explicit length";for(int i=0;i<x.ExplicitIndices.Length;i++)if(x.ExplicitIndices[i]!=y.ExplicitIndices[i])return "explicit "+i+" of "+x.ExplicitCount;var xb=(int[])Buckets.GetValue(x);var yb=(int[])Buckets.GetValue(y);if(xb.Length!=yb.Length)return "bucket length";for(int i=0;i<xb.Length;i++)if(xb[i]!=yb[i])return "bucket "+i;if(a.m_SerializedExplicitTags.Count!=b.m_SerializedExplicitTags.Count||a.m_SerializedExplicitTags.Capacity!=b.m_SerializedExplicitTags.Capacity)return "cache";return null;}
 static bool Admit(GameplayTagContainer c,GameplayTagContainer source){var a=c.Indices.Storage;var b=source.Indices.Storage;if(a.Count<=0||a.ExplicitCount<=0||a.Count<b.Count)return false;foreach(var s in new[]{a,b}){for(int i=0;i<s.ExplicitCount;i++){int index=s.ExplicitIndices[i];if((uint)index>=(uint)s.Count||s.Entries[index].ExplicitCount!=1||s.Entries[index].ExplicitIndex!=i)return false;}for(int i=0;i<s.Count;i++){var e=s.Entries[i];if(e.Count<=0||(e.ExplicitCount!=0&&e.ExplicitCount!=1))return false;if(e.ExplicitCount==1&&((uint)e.ExplicitIndex>=(uint)s.ExplicitCount||s.ExplicitIndices[e.ExplicitIndex]!=i))return false;}}return true;}
 static void Run(int recipe,int count,int shape,int reserve,int srcRecipe,int srcCount,int srcShape,bool aliasRight){var expected=Make(recipe,count,shape,reserve);var actual=Make(recipe,count,shape,reserve);var source=Make(srcRecipe,srcCount,srcShape,0);if(!Admit(actual,source)||(aliasRight&&actual.TagCount==source.TagCount)){Skipped++;return;}string id=recipe+"/"+count+"/"+shape+"/"+reserve+"/"+srcRecipe+"/"+srcCount+"/"+srcShape+"/"+aliasRight;if(Diff(expected,actual)!=null)throw new Exception("setup");var er=Refs(expected);var ar=Refs(actual);if(aliasRight)GameplayTagContainer.Copy(expected,GameplayTagContainer.Union(source,expected));else GameplayTagContainer.Copy(expected,GameplayTagContainer.Union(expected,source));if(!actual.Indices.Storage.CanReuseSelectedUnionSeed(source.Indices.Storage))throw new Exception(id+" approved diagnostic state rejected");if(aliasRight)GameplayTagContainer.Union(actual,source,actual);else GameplayTagContainer.Union(actual,actual,source);var diff=Diff(expected,actual);if(diff!=null)throw new Exception(id+" union differs: "+diff);if(Identity(er,expected)!=Identity(ar,actual))throw new Exception(id+" identity differs");for(int i=0;i<12;i++){var t=Flat[(recipe*31+i*29)%Flat.Length];expected.AddTag(t);actual.AddTag(t);expected.RemoveTag(t);actual.RemoveTag(t);diff=Diff(expected,actual);if(diff!=null)throw new Exception(id+" mutation continuation: "+diff);}expected.Clear();actual.Clear();expected.AddTag(Deep[256]);actual.AddTag(Deep[256]);diff=Diff(expected,actual);if(diff!=null)throw new Exception(id+" clear/regrow: "+diff);Cases++;}
 static void Main(){Register();foreach(int reserve in new[]{0,8,32,128,1024,8192})foreach(int recipe in new[]{0,1,2,3,4,7})foreach(int count in new[]{1,8,9,17,65,128,257})foreach(int shape in new[]{0,1,3})foreach(int srcCount in new[]{1,8,9,65,128})foreach(int srcShape in new[]{0,1})foreach(bool right in new[]{false,true})Run(recipe,count,shape,reserve,recipe+11,srcCount,srcShape,right);Console.WriteLine("PASS selected-seed diagnostic: "+Cases+" admitted complete-owned-state/identity/continuation cases, "+Skipped+" excluded; actual selected-seed candidate API; no timing");}
}
